head.script:
// 테스트 설명, 유효성 값 설정
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (설정 영역 con 옵션 미생성)
//  - description 첫 문장(들여쓰기 표현방식 설정)은 propval 항목("nbsp" / 미설정 / "div" / "line" / "none") 으로 검증
//  - "none" 의 propval 문장과 | 문장은 같은 동작을 서술하므로 1개 항목으로 통합
scwin.tData = {
    "description" : "[column > P > depthType]<br/>inputType='drilldown' 인 Column 에서 계층 깊이를 나타내는 들여쓰기의 표현방식을 설정합니다.",
    "validation" : [
        "Column 의 depthColumn 속성으로 계층 깊이 값이 지정되어야 동작합니다.",
        "'nbsp' 설정 시, 계층 단계마다 공백 문자 2 개를 데이터 앞에 표시합니다.",
        "미설정 시, 계층 단계마다 공백 문자 2 개를 데이터 앞에 표시합니다.",
        "'div' 설정 시, 계층 단계마다 16px 폭의 빈 div 요소를 데이터 앞에 표시합니다.",
        "'line' 설정 시, 계층 단계마다 계층 연결선 이미지를 데이터 앞에 표시합니다.",
        "'line' 설정 시, 한 단계의 폭은 16px 이며 연결선 이미지는 마지막 Row 를 다르게 표시합니다.",
        "'none' 설정 시, 계층 단계를 표시하지 않습니다. 모든 Row 의 데이터가 같은 좌측위치에서 시작합니다.",
        "최상위 Row 는 기본적으로 계층 깊이가 표시되지 않습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (depthType 미설정, depthColumn=depth)
    con_depthType.setSelectedIndex(0);
    con_depthColumn.setValue("depth");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 조직 데이터 (10건, 깊이 1 ~ 3 의 3단계 계층)
//  - depth : 계층 깊이 값 (depthStartIndex 미설정 = 기본값 1 기준으로 1 부터 시작)
//  - 같은 부모의 마지막 자식 Row : 재무팀, 영업본부, 영업2팀, 개발센터, 플랫폼팀
//    (line 은 형제 Row 중 마지막인지로 본인 단계 이미지를 line_L / line_T 로, 상위 단계는 부모가 마지막이면 빈칸 / 아니면 line_I 로 구분)
scwin.rowData = [
    { "name" : "본사", "depth" : "1" },
    { "name" : "경영지원본부", "depth" : "2" },
    { "name" : "인사팀", "depth" : "3" },
    { "name" : "재무팀", "depth" : "3" },
    { "name" : "영업본부", "depth" : "2" },
    { "name" : "영업1팀", "depth" : "3" },
    { "name" : "영업2팀", "depth" : "3" },
    { "name" : "연구소", "depth" : "1" },
    { "name" : "개발센터", "depth" : "2" },
    { "name" : "플랫폼팀", "depth" : "3" }
];



// comp 생성
//  - name  : 검증 대상 Body Column (inputType=drilldown, depthType = con_depthType, depthColumn = con_depthColumn)
//  - depth : 계층 깊이 값 표시용 Column
//  - showDepth / depthStartIndex 는 설정하지 않음 (전체 Row 펼침, 깊이 값 1 부터)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 조직명 Column 에 inputType=drilldown 적용, 계층 깊이 값은 1 ~ 3 (depthStartIndex 기본값 1)\n[확인] (계층 상태 확인) 버튼으로 Row 별 깊이 값 / 들여쓰기 요소 / 데이터 시작 위치(px) 확인\n[line] 같은 부모의 마지막 자식 Row (재무팀, 영업본부, 영업2팀, 개발센터, 플랫폼팀) 와 아닌 Row 의 연결선 이미지 비교"', '', 'label1');

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let properties = {
        depthType : con_depthType.getValue(),
        depthColumn : con_depthColumn.getValue()
    };
    let cList = $c.gcm.createCList(properties);

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="조직명" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depth" name="깊이" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.rowData, false);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:400px;height:450px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="250" style="" inputType="text" id="column1" value="조직명 (drilldown)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="깊이 (depth)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="250" style="text-align:left;" inputType="drilldown" id="name" value="" ' + cList + '></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="depth" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1 ~ 8 판정 출력 : 전체 데이터 Row 의 조직명 / 깊이 값 / 들여쓰기 요소 / 데이터 시작 위치
//  - 들여쓰기 요소 : 조직명 Cell 의 데이터 앞 공백 문자(nbsp) 개수, 빈 div 요소(자식 없는 들여쓰기 div)의 개수 · 폭 · 연결선 이미지 파일명
//    (펼침/접힘 아이콘을 감싸는 div 는 자식이 있으므로 들여쓰기 요소에서 제외)
//  - 데이터 시작 위치 : 조직명 Cell 왼쪽 경계부터 데이터 텍스트 시작까지의 거리(px)
//  - 빈 div 폭은 23px 로 출력됨 : 프로젝트 테마 cm/css/base.css 의 .w2grid .w2grid_depthBlank {width:23px} 가 엔진 기본 16px 를 덮어씀 (테마 유지, 엔진 기준은 16px)
scwin.btn_checkStatus_onclick = function () {
    let depthColumn = con_depthColumn.getValue();
    let shown = {};
    let displayLength = target1.getDataLength();
    for (let i = 0; i < displayLength; i++) {
        shown[target1.getRealRowIndex(i)] = i;
    }
    let arrAll = dlt_bind.getAllJSON();
    let totalRow = target1.getTotalRow();
    for (let r = 0; r < totalRow; r++) {
        let str = "Row " + r + " '" + arrAll[r].name + "'";
        if (depthColumn !== "") {
            str += " / 깊이 값 : " + arrAll[r][depthColumn];
        }
        if (shown[r] === undefined) {
            wf_body_bottom.getObj("scwin").setReturnValue(str + " / 숨김");
            continue;
        }
        let td = document.querySelector("#" + target1.id + " td[id$='_cell_" + shown[r] + "_0']");
        if (!td) {
            wf_body_bottom.getObj("scwin").setReturnValue(str + " / Cell 없음");
            continue;
        }
        let tdLeft = td.getBoundingClientRect().left;

        // 공백 문자 / 데이터 텍스트 노드
        let nbspCount = 0;
        let dataNode = null;
        let walker = document.createTreeWalker(td, NodeFilter.SHOW_TEXT, null);
        let node;
        while ((node = walker.nextNode())) {
            let text = node.nodeValue;
            if (text.replace(/ /g, "").trim() === "") {
                nbspCount += (text.match(/ /g) || []).length;
            } else {
                dataNode = node;
            }
        }

        // 들여쓰기 div (자식 요소가 없는 w2grid_depth* div)
        let arrDepth = [];
        let divs = td.querySelectorAll("div[class*='w2grid_depth']");
        for (let i = 0; i < divs.length; i++) {
            if (divs[i].children.length > 0) continue;
            let bg = window.getComputedStyle(divs[i]).backgroundImage;
            let img = (bg && bg !== "none") ? bg.replace(/^.*\//, "").replace(/["')]+$/, "") : "빈 div";
            arrDepth.push(img + " " + Math.round(divs[i].getBoundingClientRect().width) + "px");
        }

        let arrIndent = [];
        if (nbspCount > 0) arrIndent.push("공백 문자 " + nbspCount + "개");
        if (arrDepth.length > 0) arrIndent.push("div " + arrDepth.length + "개 [" + arrDepth.join(", ") + "]");
        str += " / 들여쓰기 : " + (arrIndent.length > 0 ? arrIndent.join(", ") : "없음");

        if (dataNode) {
            let range = document.createRange();
            range.selectNodeContents(dataNode);
            str += " / 데이터 시작 위치 : " + Math.round(range.getBoundingClientRect().left - tdLeft) + "px";
        }
        wf_body_bottom.getObj("scwin").setReturnValue(str);
    }
}
